(5984, 515, 'faq_topics_4_topic_name', 'Shipping & Warranty'),
(5985, 515, '_faq_topics_4_topic_name', 'field_topic_name'),
(5986, 515, 'faq_topics_4_topic_slug', 'shipping-warranty'),
(5987, 515, '_faq_topics_4_topic_slug', 'field_topic_slug'),
(5988, 515, 'faq_items_3_category_slug', 'the-app'),
(5989, 515, '_faq_items_3_category_slug', 'field_faq_item_topic_slug'),
(5990, 515, 'faq_items_3_question', 'Does the app work without an internet connection?'),
(5991, 515, '_faq_items_3_question', 'field_faq_item_question'),
(5992, 515, 'faq_items_3_answer', 'To use remote control features from your phone, an active Wi-Fi connection is required. However, the physical touch panel on the purifier always works offline.'),
(5993, 515, '_faq_items_3_answer', 'field_faq_item_answer'),
(5994, 515, 'faq_items_4_category_slug', 'air-quality'),
(5995, 515, '_faq_items_4_category_slug', 'field_faq_item_topic_slug'),
(5996, 515, 'faq_items_4_question', 'What does the AQI number actually mean?'),
(5997, 515, '_faq_items_4_question', 'field_faq_item_question'),
(5998, 515, 'faq_items_4_answer', 'AQI stands for Air Quality Index. It is a standard scale used to communicate how polluted the air currently is. Lower numbers (0-50) indicate excellent air quality, while higher numbers indicate unsafe levels of particulate matter.'),
(5999, 515, '_faq_items_4_answer', 'field_faq_item_answer'),
(6000, 515, 'faq_items_5_category_slug', 'air-quality'),
(6001, 515, '_faq_items_5_category_slug', 'field_faq_item_topic_slug'),
(6002, 515, 'faq_items_5_question', 'What pollutants does the sensor measure?'),
(6003, 515, '_faq_items_5_question', 'field_faq_item_question'),
(6004, 515, 'faq_items_5_answer', 'Our laser sensors actively scan the air for PM2.5 (fine inhalable particles) and PM10 (dust and pollen). The Air Pro Max also includes a dedicated VOC sensor for harmful gases.'),
(6005, 515, '_faq_items_5_answer', 'field_faq_item_answer'),
(6006, 515, 'faq_items_6_category_slug', 'air-quality'),
(6007, 515, '_faq_items_6_category_slug', 'field_faq_item_topic_slug'),
(6008, 515, 'faq_items_6_question', 'Why is my indoor AQI sometimes higher than outdoor?'),
(6009, 515, '_faq_items_6_question', 'field_faq_item_question'),
(6010, 515, 'faq_items_6_answer', 'Indoor activities like cooking, using aerosols, burning incense, or sweeping can quickly elevate indoor pollution levels beyond outdoor levels due to poor ventilation.'),
(6011, 515, '_faq_items_6_answer', 'field_faq_item_answer'),
(6012, 515, 'faq_items_7_category_slug', 'filters-care'),
(6013, 515, '_faq_items_7_category_slug', 'field_faq_item_topic_slug'),
(6014, 515, 'faq_items_7_question', 'How often do I need to replace the filter?'),
(6015, 515, '_faq_items_7_question', 'field_faq_item_question'),
(6016, 515, 'faq_items_7_answer', 'Generally every 8 to 12 months, depending on usage and local air quality. The purifier and the app will notify you when it\'s time to replace it.'),
(6017, 515, '_faq_items_7_answer', 'field_faq_item_answer'),
