(6066, 535, 'faq_items_0_category_slug', 'the-app'),
(6067, 535, '_faq_items_0_category_slug', 'field_faq_item_topic_slug'),
(6068, 535, 'faq_items_0_question', 'Which devices is the Breathe In app available on?'),
(6069, 535, '_faq_items_0_question', 'field_faq_item_question'),
(6070, 535, 'faq_items_0_answer', 'The app is available for download on both iOS (App Store) and Android (Google Play Store) devices running the latest software versions.'),
(6071, 535, '_faq_items_0_answer', 'field_faq_item_answer'),
(6072, 535, 'faq_items_1_category_slug', 'the-app'),
(6073, 535, '_faq_items_1_category_slug', 'field_faq_item_topic_slug'),
(6074, 535, 'faq_items_1_question', 'How many purifiers can I connect to one account?'),
(6075, 535, '_faq_items_1_question', 'field_faq_item_question'),
(6076, 535, 'faq_items_1_answer', 'You can connect and manage up to 50 purifiers on a single account, making it ideal for both residential  and large commercial setups.'),
(6077, 535, '_faq_items_1_answer', 'field_faq_item_answer'),
(6078, 535, 'faq_items_2_category_slug', 'the-app'),
(6079, 535, '_faq_items_2_category_slug', 'field_faq_item_topic_slug'),
(6080, 535, 'faq_items_2_question', 'Can I share access with family members?'),
(6081, 535, '_faq_items_2_question', 'field_faq_item_question'),
(6082, 535, 'faq_items_2_answer', 'Yes, using the \"Home Management\" feature in the app, you can invite family members to control the purifiers without them needing to re-pair the devices.'),
(6083, 535, '_faq_items_2_answer', 'field_faq_item_answer'),
(6084, 535, 'faq_items', '8'),
(6085, 535, '_faq_items', 'field_faq_items_repeater'),
(6086, 535, 'faq_topics_2_topic_name', 'Filters & Care'),
(6087, 535, '_faq_topics_2_topic_name', 'field_topic_name'),
(6088, 535, 'faq_topics_2_topic_slug', 'filters-care'),
(6089, 535, '_faq_topics_2_topic_slug', 'field_topic_slug'),
(6090, 535, 'faq_topics_3_topic_name', 'Technical'),
(6091, 535, '_faq_topics_3_topic_name', 'field_topic_name'),
(6092, 535, 'faq_topics_3_topic_slug', 'technical'),
(6093, 535, '_faq_topics_3_topic_slug', 'field_topic_slug'),
(6094, 535, 'faq_topics_4_topic_name', 'Shipping & Warranty'),
(6095, 535, '_faq_topics_4_topic_name', 'field_topic_name'),
(6096, 535, 'faq_topics_4_topic_slug', 'shipping-warranty'),
(6097, 535, '_faq_topics_4_topic_slug', 'field_topic_slug'),
(6098, 535, 'faq_items_3_category_slug', 'the-app'),
(6099, 535, '_faq_items_3_category_slug', 'field_faq_item_topic_slug'),
(6100, 535, 'faq_items_3_question', 'Does the app work without an internet connection?'),
(6101, 535, '_faq_items_3_question', 'field_faq_item_question'),
(6102, 535, 'faq_items_3_answer', 'To use remote control features from your phone, an active Wi-Fi connection is required. However, the physical touch panel on the purifier always works offline.'),
(6103, 535, '_faq_items_3_answer', 'field_faq_item_answer'),
(6104, 535, 'faq_items_4_category_slug', 'air-quality'),
(6105, 535, '_faq_items_4_category_slug', 'field_faq_item_topic_slug'),
(6106, 535, 'faq_items_4_question', 'What does the AQI number actually mean?'),
(6107, 535, '_faq_items_4_question', 'field_faq_item_question'),
(6108, 535, 'faq_items_4_answer', 'AQI stands for Air Quality Index. It is a standard scale used to communicate how polluted the air currently is. Lower numbers (0-50) indicate excellent air quality, while higher numbers indicate unsafe levels of particulate matter.'),
(6109, 535, '_faq_items_4_answer', 'field_faq_item_answer'),
(6110, 535, 'faq_items_5_category_slug', 'air-quality'),
(6111, 535, '_faq_items_5_category_slug', 'field_faq_item_topic_slug'),
(6112, 535, 'faq_items_5_question', 'What pollutants does the sensor measure?'),
(6113, 535, '_faq_items_5_question', 'field_faq_item_question'),
(6114, 535, 'faq_items_5_answer', 'Our laser sensors actively scan the air for PM2.5 (fine inhalable particles) and PM10 (dust and pollen). The Air Pro Max also includes a dedicated VOC sensor for harmful gases.'),
(6115, 535, '_faq_items_5_answer', 'field_faq_item_answer'),
(6116, 535, 'faq_items_6_category_slug', 'air-quality'),
(6117, 535, '_faq_items_6_category_slug', 'field_faq_item_topic_slug'),
(6118, 535, 'faq_items_6_question', 'Why is my indoor AQI sometimes higher than outdoor?'),
(6119, 535, '_faq_items_6_question', 'field_faq_item_question'),
(6120, 535, 'faq_items_6_answer', 'Indoor activities like cooking, using aerosols, burning incense, or sweeping can quickly elevate indoor pollution levels beyond outdoor levels due to poor ventilation.'),
(6121, 535, '_faq_items_6_answer', 'field_faq_item_answer'),
(6122, 535, 'faq_items_7_category_slug', 'filters-care'),
(6123, 535, '_faq_items_7_category_slug', 'field_faq_item_topic_slug'),
(6124, 535, 'faq_items_7_question', 'How often do I need to replace the filter?'),
(6125, 535, '_faq_items_7_question', 'field_faq_item_question'),
(6126, 535, 'faq_items_7_answer', 'Generally every 8 to 12 months, depending on usage and local air quality. The purifier and the app will notify you when it\'s time to replace it.'),
(6127, 535, '_faq_items_7_answer', 'field_faq_item_answer'),
(6128, 515, 'faq_items_8_category_slug', 'filters-care'),
(6129, 515, '_faq_items_8_category_slug', 'field_faq_item_topic_slug'),
(6130, 515, 'faq_items_8_question', 'Can I wash and reuse the HEPA filter?'),
(6131, 515, '_faq_items_8_question', 'field_faq_item_question'),
(6132, 515, 'faq_items_8_answer', 'No. Washing a HEPA filter destroys its delicate microscopic fibers. You can gently vacuum the outer pre-filter layer, but the main filter block must be replaced.'),
(6133, 515, '_faq_items_8_answer', 'field_faq_item_answer'),
(6134, 515, 'faq_items_9_category_slug', 'filters-care'),
(6135, 515, '_faq_items_9_category_slug', 'field_faq_item_topic_slug'),
(6136, 515, 'faq_items_9_question', 'Where can I buy replacement filters?'),
(6137, 515, '_faq_items_9_question', 'field_faq_item_question'),
(6138, 515, 'faq_items_9_answer', 'Genuine replacements are available directly on our website, through the Breathe In app, or via our official Amazon storefront.'),
(6139, 515, '_faq_items_9_answer', 'field_faq_item_answer'),
(6140, 515, 'faq_items_10_category_slug', 'technical'),
(6141, 515, '_faq_items_10_category_slug', 'field_faq_item_topic_slug'),
(6142, 515, 'faq_items_10_question', 'What Wi-Fi frequency does the purifier support?'),
(6143, 515, '_faq_items_10_question', 'field_faq_item_question'),
(6144, 515, 'faq_items_10_answer', 'Our purifiers currently support standard 2.4GHz Wi-Fi networks (which offer better range through walls). They will not connect to a 5GHz-only network.'),
(6145, 515, '_faq_items_10_answer', 'field_faq_item_answer'),
(6146, 515, 'faq_items_11_category_slug', 'technical'),
(6147, 515, '_faq_items_11_category_slug', 'field_faq_item_topic_slug'),
(6148, 515, 'faq_items_11_question', 'My purifier won\'t pair. What should I try?'),
(6149, 515, '_faq_items_11_question', 'field_faq_item_question'),
(6150, 515, 'faq_items_11_answer', 'Ensure your phone is connected to a 2.4GHz network. Press and hold the Wi-Fi button on the purifier panel for 5 seconds until it flashes rapidly, then retry the pairing process in the app.'),
(6151, 515, '_faq_items_11_answer', 'field_faq_item_answer'),
(6152, 515, 'faq_items_12_category_slug', 'technical'),
(6153, 515, '_faq_items_12_category_slug', 'field_faq_item_topic_slug'),
(6154, 515, 'faq_items_12_question', 'How loud is Sleep Mode?'),
(6155, 515, '_faq_items_12_question', 'field_faq_item_question'),
(6156, 515, 'faq_items_12_answer', 'In Sleep Mode, the fan operates at a whisper-quiet 24 decibels — roughly the volume of rustling leaves, making it perfect for uninterrupted sleep.'),
(6157, 515, '_faq_items_12_answer', 'field_faq_item_answer'),
(6158, 515, 'faq_items_13_category_slug', 'shipping-warranty'),
(6159, 515, '_faq_items_13_category_slug', 'field_faq_item_topic_slug'),
(6160, 515, 'faq_items_13_question', 'How long does delivery take?'),
(6161, 515, '_faq_items_13_question', 'field_faq_item_question'),
(6162, 515, 'faq_items_13_answer', 'Standard delivery takes 3-5 business days to most metro locations across India.'),
(6163, 515, '_faq_items_13_answer', 'field_faq_item_answer'),
(6164, 515, 'faq_items_14_category_slug', 'shipping-warranty'),
(6165, 515, '_faq_items_14_category_slug', 'field_faq_item_topic_slug'),
(6166, 515, 'faq_items_14_question', 'What does the warranty cover?'),
(6167, 515, '_faq_items_14_question', 'field_faq_item_question'),
(6168, 515, 'faq_items_14_answer', 'We offer a comprehensive 2-year warranty that covers the motor and internal electronics. Physical damage and consumable filters are not covered.'),
(6169, 515, '_faq_items_14_answer', 'field_faq_item_answer'),
(6170, 515, 'faq_items_15_category_slug', 'shipping-warranty'),
(6171, 515, '_faq_items_15_category_slug', 'field_faq_item_topic_slug'),
(6172, 515, 'faq_items_15_question', 'Can I return the purifier if I\'m not satisfied?'),
(6173, 515, '_faq_items_15_question', 'field_faq_item_question'),
(6174, 515, 'faq_items_15_answer', 'Yes, we offer a 14-day risk-free trial. If you are not completely satisfied, you can return the unit within 14 days in its original condition and packaging.'),
(6175, 515, '_faq_items_15_answer', 'field_faq_item_answer'),
