(6388, 537, 'faq_items_0_category_slug', 'the-app'),
(6389, 537, '_faq_items_0_category_slug', 'field_faq_item_topic_slug'),
(6390, 537, 'faq_items_0_question', 'Which devices is the Breathe In app available on?'),
(6391, 537, '_faq_items_0_question', 'field_faq_item_question'),
(6392, 537, 'faq_items_0_answer', 'The app is available for download on both iOS (App Store) and Android (Google Play Store) devices running the latest software versions.'),
(6393, 537, '_faq_items_0_answer', 'field_faq_item_answer'),
(6394, 537, 'faq_items_1_category_slug', 'the-app'),
(6395, 537, '_faq_items_1_category_slug', 'field_faq_item_topic_slug'),
(6396, 537, 'faq_items_1_question', 'How many purifiers can I connect to one account?'),
(6397, 537, '_faq_items_1_question', 'field_faq_item_question'),
(6398, 537, 'faq_items_1_answer', 'You can connect and manage up to 50 purifiers on a single account, making it ideal for both residential  and large commercial setups.'),
(6399, 537, '_faq_items_1_answer', 'field_faq_item_answer'),
(6400, 537, 'faq_items_2_category_slug', 'the-app'),
(6401, 537, '_faq_items_2_category_slug', 'field_faq_item_topic_slug'),
(6402, 537, 'faq_items_2_question', 'Can I share access with family members?'),
(6403, 537, '_faq_items_2_question', 'field_faq_item_question'),
(6404, 537, 'faq_items_2_answer', 'Yes, using the \"Home Management\" feature in the app, you can invite family members to control the purifiers without them needing to re-pair the devices.'),
(6405, 537, '_faq_items_2_answer', 'field_faq_item_answer'),
(6406, 537, 'faq_items', '16'),
(6407, 537, '_faq_items', 'field_faq_items_repeater'),
