(6409, 537, '_faq_topics_2_topic_name', 'field_topic_name'),
(6410, 537, 'faq_topics_2_topic_slug', 'filters-care'),
(6411, 537, '_faq_topics_2_topic_slug', 'field_topic_slug'),
(6412, 537, 'faq_topics_3_topic_name', 'Technical'),
(6413, 537, '_faq_topics_3_topic_name', 'field_topic_name'),
(6414, 537, 'faq_topics_3_topic_slug', 'technical'),
(6415, 537, '_faq_topics_3_topic_slug', 'field_topic_slug'),
(6416, 537, 'faq_topics_4_topic_name', 'Shipping & Warranty'),
(6417, 537, '_faq_topics_4_topic_name', 'field_topic_name'),
(6418, 537, 'faq_topics_4_topic_slug', 'shipping-warranty'),
(6419, 537, '_faq_topics_4_topic_slug', 'field_topic_slug'),
(6420, 537, 'faq_items_3_category_slug', 'the-app'),
(6421, 537, '_faq_items_3_category_slug', 'field_faq_item_topic_slug'),
(6422, 537, 'faq_items_3_question', 'Does the app work without an internet connection?'),
(6423, 537, '_faq_items_3_question', 'field_faq_item_question'),
(6424, 537, 'faq_items_3_answer', 'To use remote control features from your phone, an active Wi-Fi connection is required. However, the physical touch panel on the purifier always works offline.'),
(6425, 537, '_faq_items_3_answer', 'field_faq_item_answer'),
(6426, 537, 'faq_items_4_category_slug', 'air-quality'),
(6427, 537, '_faq_items_4_category_slug', 'field_faq_item_topic_slug'),
(6428, 537, 'faq_items_4_question', 'What does the AQI number actually mean?'),
(6429, 537, '_faq_items_4_question', 'field_faq_item_question'),
(6430, 537, 'faq_items_4_answer', 'AQI stands for Air Quality Index. It is a standard scale used to communicate how polluted the air currently is. Lower numbers (0-50) indicate excellent air quality, while higher numbers indicate unsafe levels of particulate matter.'),
(6431, 537, '_faq_items_4_answer', 'field_faq_item_answer'),
(6432, 537, 'faq_items_5_category_slug', 'air-quality'),
(6433, 537, '_faq_items_5_category_slug', 'field_faq_item_topic_slug'),
(6434, 537, 'faq_items_5_question', 'What pollutants does the sensor measure?'),
(6435, 537, '_faq_items_5_question', 'field_faq_item_question'),
(6436, 537, 'faq_items_5_answer', 'Our laser sensors actively scan the air for PM2.5 (fine inhalable particles) and PM10 (dust and pollen). The Air Pro Max also includes a dedicated VOC sensor for harmful gases.'),
(6437, 537, '_faq_items_5_answer', 'field_faq_item_answer'),
(6438, 537, 'faq_items_6_category_slug', 'air-quality'),
(6439, 537, '_faq_items_6_category_slug', 'field_faq_item_topic_slug'),
(6440, 537, 'faq_items_6_question', 'Why is my indoor AQI sometimes higher than outdoor?'),
(6441, 537, '_faq_items_6_question', 'field_faq_item_question'),
(6442, 537, 'faq_items_6_answer', 'Indoor activities like cooking, using aerosols, burning incense, or sweeping can quickly elevate indoor pollution levels beyond outdoor levels due to poor ventilation.'),
(6443, 537, '_faq_items_6_answer', 'field_faq_item_answer'),
(6444, 537, 'faq_items_7_category_slug', 'filters-care'),
(6445, 537, '_faq_items_7_category_slug', 'field_faq_item_topic_slug'),
(6446, 537, 'faq_items_7_question', 'How often do I need to replace the filter?'),
(6447, 537, '_faq_items_7_question', 'field_faq_item_question'),
(6448, 537, 'faq_items_7_answer', 'Generally every 8 to 12 months, depending on usage and local air quality. The purifier and the app will notify you when it\'s time to replace it.'),
(6449, 537, '_faq_items_7_answer', 'field_faq_item_answer'),
(6450, 537, 'faq_items_8_category_slug', 'filters-care'),
(6451, 537, '_faq_items_8_category_slug', 'field_faq_item_topic_slug'),
(6452, 537, 'faq_items_8_question', 'Can I wash and reuse the HEPA filter?'),
(6453, 537, '_faq_items_8_question', 'field_faq_item_question'),
(6454, 537, 'faq_items_8_answer', 'No. Washing a HEPA filter destroys its delicate microscopic fibers. You can gently vacuum the outer pre-filter layer, but the main filter block must be replaced.'),
(6455, 537, '_faq_items_8_answer', 'field_faq_item_answer'),
(6456, 537, 'faq_items_9_category_slug', 'filters-care'),
(6457, 537, '_faq_items_9_category_slug', 'field_faq_item_topic_slug'),
(6458, 537, 'faq_items_9_question', 'Where can I buy replacement filters?'),
(6459, 537, '_faq_items_9_question', 'field_faq_item_question'),
(6460, 537, 'faq_items_9_answer', 'Genuine replacements are available directly on our website, through the Breathe In app, or via our official Amazon storefront.'),
(6461, 537, '_faq_items_9_answer', 'field_faq_item_answer'),
(6462, 537, 'faq_items_10_category_slug', 'technical'),
(6463, 537, '_faq_items_10_category_slug', 'field_faq_item_topic_slug'),
(6464, 537, 'faq_items_10_question', 'What Wi-Fi frequency does the purifier support?'),
(6465, 537, '_faq_items_10_question', 'field_faq_item_question'),
(6466, 537, 'faq_items_10_answer', 'Our purifiers currently support standard 2.4GHz Wi-Fi networks (which offer better range through walls). They will not connect to a 5GHz-only network.'),
(6467, 537, '_faq_items_10_answer', 'field_faq_item_answer'),
(6468, 537, 'faq_items_11_category_slug', 'technical'),
(6469, 537, '_faq_items_11_category_slug', 'field_faq_item_topic_slug'),
(6470, 537, 'faq_items_11_question', 'My purifier won\'t pair. What should I try?'),
(6471, 537, '_faq_items_11_question', 'field_faq_item_question'),
(6472, 537, 'faq_items_11_answer', 'Ensure your phone is connected to a 2.4GHz network. Press and hold the Wi-Fi button on the purifier panel for 5 seconds until it flashes rapidly, then retry the pairing process in the app.'),
(6473, 537, '_faq_items_11_answer', 'field_faq_item_answer'),
(6474, 537, 'faq_items_12_category_slug', 'technical'),
(6475, 537, '_faq_items_12_category_slug', 'field_faq_item_topic_slug'),
(6476, 537, 'faq_items_12_question', 'How loud is Sleep Mode?'),
(6477, 537, '_faq_items_12_question', 'field_faq_item_question'),
(6478, 537, 'faq_items_12_answer', 'In Sleep Mode, the fan operates at a whisper-quiet 24 decibels — roughly the volume of rustling leaves, making it perfect for uninterrupted sleep.'),
(6479, 537, '_faq_items_12_answer', 'field_faq_item_answer'),
(6480, 537, 'faq_items_13_category_slug', 'shipping-warranty'),
(6481, 537, '_faq_items_13_category_slug', 'field_faq_item_topic_slug'),
(6482, 537, 'faq_items_13_question', 'How long does delivery take?'),
(6483, 537, '_faq_items_13_question', 'field_faq_item_question'),
(6484, 537, 'faq_items_13_answer', 'Standard delivery takes 3-5 business days to most metro locations across India.'),
(6485, 537, '_faq_items_13_answer', 'field_faq_item_answer'),
(6486, 537, 'faq_items_14_category_slug', 'shipping-warranty'),
(6487, 537, '_faq_items_14_category_slug', 'field_faq_item_topic_slug'),
(6488, 537, 'faq_items_14_question', 'What does the warranty cover?'),
(6489, 537, '_faq_items_14_question', 'field_faq_item_question'),
(6490, 537, 'faq_items_14_answer', 'We offer a comprehensive 2-year warranty that covers the motor and internal electronics. Physical damage and consumable filters are not covered.'),
(6491, 537, '_faq_items_14_answer', 'field_faq_item_answer'),
(6492, 537, 'faq_items_15_category_slug', 'shipping-warranty'),
(6493, 537, '_faq_items_15_category_slug', 'field_faq_item_topic_slug'),
(6494, 537, 'faq_items_15_question', 'Can I return the purifier if I\'m not satisfied?'),
(6495, 537, '_faq_items_15_question', 'field_faq_item_question'),
(6496, 537, 'faq_items_15_answer', 'Yes, we offer a 14-day risk-free trial. If you are not completely satisfied, you can return the unit within 14 days in its original condition and packaging.'),
(6497, 537, '_faq_items_15_answer', 'field_faq_item_answer'),
