(6560, 538, 'faq_items_0_category_slug', 'the-app'),
(6561, 538, '_faq_items_0_category_slug', 'field_faq_item_topic_slug'),
(6562, 538, 'faq_items_0_question', 'Which devices is the Breathe In app available on?'),
(6563, 538, '_faq_items_0_question', 'field_faq_item_question'),
(6564, 538, 'faq_items_0_answer', 'The app is available for download on both iOS (App Store) and Android (Google Play Store) devices running the latest software versions.'),
(6565, 538, '_faq_items_0_answer', 'field_faq_item_answer'),
(6566, 538, 'faq_items_1_category_slug', 'the-app'),
(6567, 538, '_faq_items_1_category_slug', 'field_faq_item_topic_slug'),
(6568, 538, 'faq_items_1_question', 'How many purifiers can I connect to one account?'),
(6569, 538, '_faq_items_1_question', 'field_faq_item_question'),
(6570, 538, 'faq_items_1_answer', 'You can connect and manage up to 50 purifiers on a single account, making it ideal for both residential  and large commercial setups.'),
(6571, 538, '_faq_items_1_answer', 'field_faq_item_answer'),
(6572, 538, 'faq_items_2_category_slug', 'the-app'),
(6573, 538, '_faq_items_2_category_slug', 'field_faq_item_topic_slug'),
(6574, 538, 'faq_items_2_question', 'Can I share access with family members?'),
(6575, 538, '_faq_items_2_question', 'field_faq_item_question'),
(6576, 538, 'faq_items_2_answer', 'Yes, using the \"Home Management\" feature in the app, you can invite family members to control the purifiers without them needing to re-pair the devices.'),
(6577, 538, '_faq_items_2_answer', 'field_faq_item_answer'),
(6578, 538, 'faq_items', '16'),
(6579, 538, '_faq_items', 'field_faq_items_repeater'),
(6580, 538, 'faq_topics_2_topic_name', 'Filters & Care'),
(6581, 538, '_faq_topics_2_topic_name', 'field_topic_name'),
(6582, 538, 'faq_topics_2_topic_slug', 'filters-care'),
(6583, 538, '_faq_topics_2_topic_slug', 'field_topic_slug'),
(6584, 538, 'faq_topics_3_topic_name', 'Technical'),
(6585, 538, '_faq_topics_3_topic_name', 'field_topic_name'),
(6586, 538, 'faq_topics_3_topic_slug', 'technical'),
(6587, 538, '_faq_topics_3_topic_slug', 'field_topic_slug'),
(6588, 538, 'faq_topics_4_topic_name', 'Shipping & Warranty'),
(6589, 538, '_faq_topics_4_topic_name', 'field_topic_name'),
(6590, 538, 'faq_topics_4_topic_slug', 'shipping-warranty'),
(6591, 538, '_faq_topics_4_topic_slug', 'field_topic_slug'),
(6592, 538, 'faq_items_3_category_slug', 'the-app'),
(6593, 538, '_faq_items_3_category_slug', 'field_faq_item_topic_slug'),
(6594, 538, 'faq_items_3_question', 'Does the app work without an internet connection?'),
(6595, 538, '_faq_items_3_question', 'field_faq_item_question'),
(6596, 538, 'faq_items_3_answer', 'To use remote control features from your phone, an active Wi-Fi connection is required. However, the physical touch panel on the purifier always works offline.'),
(6597, 538, '_faq_items_3_answer', 'field_faq_item_answer'),
(6598, 538, 'faq_items_4_category_slug', 'air-quality'),
(6599, 538, '_faq_items_4_category_slug', 'field_faq_item_topic_slug'),
(6600, 538, 'faq_items_4_question', 'What does the AQI number actually mean?'),
(6601, 538, '_faq_items_4_question', 'field_faq_item_question'),
(6602, 538, 'faq_items_4_answer', 'AQI stands for Air Quality Index. It is a standard scale used to communicate how polluted the air currently is. Lower numbers (0-50) indicate excellent air quality, while higher numbers indicate unsafe levels of particulate matter.'),
(6603, 538, '_faq_items_4_answer', 'field_faq_item_answer'),
(6604, 538, 'faq_items_5_category_slug', 'air-quality'),
(6605, 538, '_faq_items_5_category_slug', 'field_faq_item_topic_slug'),
(6606, 538, 'faq_items_5_question', 'What pollutants does the sensor measure?'),
(6607, 538, '_faq_items_5_question', 'field_faq_item_question'),
(6608, 538, 'faq_items_5_answer', 'Our laser sensors actively scan the air for PM2.5 (fine inhalable particles) and PM10 (dust and pollen). The Air Pro Max also includes a dedicated VOC sensor for harmful gases.'),
(6609, 538, '_faq_items_5_answer', 'field_faq_item_answer'),
(6610, 538, 'faq_items_6_category_slug', 'air-quality'),
(6611, 538, '_faq_items_6_category_slug', 'field_faq_item_topic_slug'),
(6612, 538, 'faq_items_6_question', 'Why is my indoor AQI sometimes higher than outdoor?'),
(6613, 538, '_faq_items_6_question', 'field_faq_item_question'),
(6614, 538, 'faq_items_6_answer', 'Indoor activities like cooking, using aerosols, burning incense, or sweeping can quickly elevate indoor pollution levels beyond outdoor levels due to poor ventilation.'),
(6615, 538, '_faq_items_6_answer', 'field_faq_item_answer'),
(6616, 538, 'faq_items_7_category_slug', 'filters-care'),
(6617, 538, '_faq_items_7_category_slug', 'field_faq_item_topic_slug'),
(6618, 538, 'faq_items_7_question', 'How often do I need to replace the filter?'),
(6619, 538, '_faq_items_7_question', 'field_faq_item_question'),
(6620, 538, 'faq_items_7_answer', 'Generally every 8 to 12 months, depending on usage and local air quality. The purifier and the app will notify you when it\'s time to replace it.'),
(6621, 538, '_faq_items_7_answer', 'field_faq_item_answer'),
(6622, 538, 'faq_items_8_category_slug', 'filters-care'),
(6623, 538, '_faq_items_8_category_slug', 'field_faq_item_topic_slug'),
(6624, 538, 'faq_items_8_question', 'Can I wash and reuse the HEPA filter?'),
(6625, 538, '_faq_items_8_question', 'field_faq_item_question'),
(6626, 538, 'faq_items_8_answer', 'No. Washing a HEPA filter destroys its delicate microscopic fibers. You can gently vacuum the outer pre-filter layer, but the main filter block must be replaced.'),
(6627, 538, '_faq_items_8_answer', 'field_faq_item_answer'),
(6628, 538, 'faq_items_9_category_slug', 'filters-care'),
(6629, 538, '_faq_items_9_category_slug', 'field_faq_item_topic_slug'),
(6630, 538, 'faq_items_9_question', 'Where can I buy replacement filters?'),
(6631, 538, '_faq_items_9_question', 'field_faq_item_question'),
(6632, 538, 'faq_items_9_answer', 'Genuine replacements are available directly on our website, through the Breathe In app, or via our official Amazon storefront.'),
(6633, 538, '_faq_items_9_answer', 'field_faq_item_answer'),
(6634, 538, 'faq_items_10_category_slug', 'technical'),
(6635, 538, '_faq_items_10_category_slug', 'field_faq_item_topic_slug'),
(6636, 538, 'faq_items_10_question', 'What Wi-Fi frequency does the purifier support?'),
(6637, 538, '_faq_items_10_question', 'field_faq_item_question'),
(6638, 538, 'faq_items_10_answer', 'Our purifiers currently support standard 2.4GHz Wi-Fi networks (which offer better range through walls). They will not connect to a 5GHz-only network.'),
(6639, 538, '_faq_items_10_answer', 'field_faq_item_answer'),
(6640, 538, 'faq_items_11_category_slug', 'technical'),
(6641, 538, '_faq_items_11_category_slug', 'field_faq_item_topic_slug'),
(6642, 538, 'faq_items_11_question', 'My purifier won\'t pair. What should I try?'),
(6643, 538, '_faq_items_11_question', 'field_faq_item_question'),
(6644, 538, 'faq_items_11_answer', 'Ensure your phone is connected to a 2.4GHz network. Press and hold the Wi-Fi button on the purifier panel for 5 seconds until it flashes rapidly, then retry the pairing process in the app.'),
(6645, 538, '_faq_items_11_answer', 'field_faq_item_answer'),
(6646, 538, 'faq_items_12_category_slug', 'technical'),
(6647, 538, '_faq_items_12_category_slug', 'field_faq_item_topic_slug'),
(6648, 538, 'faq_items_12_question', 'How loud is Sleep Mode?'),
(6649, 538, '_faq_items_12_question', 'field_faq_item_question'),
(6650, 538, 'faq_items_12_answer', 'In Sleep Mode, the fan operates at a whisper-quiet 24 decibels — roughly the volume of rustling leaves, making it perfect for uninterrupted sleep.'),
(6651, 538, '_faq_items_12_answer', 'field_faq_item_answer'),
(6652, 538, 'faq_items_13_category_slug', 'shipping-warranty'),
(6653, 538, '_faq_items_13_category_slug', 'field_faq_item_topic_slug'),
(6654, 538, 'faq_items_13_question', 'How long does delivery take?'),
(6655, 538, '_faq_items_13_question', 'field_faq_item_question'),
(6656, 538, 'faq_items_13_answer', 'Standard delivery takes 3-5 business days to most metro locations across India.'),
(6657, 538, '_faq_items_13_answer', 'field_faq_item_answer'),
(6658, 538, 'faq_items_14_category_slug', 'shipping-warranty'),
(6659, 538, '_faq_items_14_category_slug', 'field_faq_item_topic_slug'),
(6660, 538, 'faq_items_14_question', 'What does the warranty cover?'),
(6661, 538, '_faq_items_14_question', 'field_faq_item_question'),
(6662, 538, 'faq_items_14_answer', 'We offer a comprehensive 2-year warranty that covers the motor and internal electronics. Physical damage and consumable filters are not covered.'),
(6663, 538, '_faq_items_14_answer', 'field_faq_item_answer'),
(6664, 538, 'faq_items_15_category_slug', 'shipping-warranty'),
(6665, 538, '_faq_items_15_category_slug', 'field_faq_item_topic_slug'),
(6666, 538, 'faq_items_15_question', 'Can I return the purifier if I\'m not satisfied?'),
(6667, 538, '_faq_items_15_question', 'field_faq_item_question'),
(6668, 538, 'faq_items_15_answer', 'Yes, we offer a 14-day risk-free trial. If you are not completely satisfied, you can return the unit within 14 days in its original condition and packaging.'),
(6669, 538, '_faq_items_15_answer', 'field_faq_item_answer'),
