(6811, 539, '_faq_items_10_answer', 'field_faq_item_answer'),
(6812, 539, 'faq_items_11_category_slug', 'technical'),
(6813, 539, '_faq_items_11_category_slug', 'field_faq_item_topic_slug'),
(6814, 539, 'faq_items_11_question', 'My purifier won\'t pair. What should I try?'),
(6815, 539, '_faq_items_11_question', 'field_faq_item_question'),
(6816, 539, 'faq_items_11_answer', 'Ensure your phone is connected to a 2.4GHz network. Press and hold the Wi-Fi button on the purifier panel for 5 seconds until it flashes rapidly, then retry the pairing process in the app.'),
(6817, 539, '_faq_items_11_answer', 'field_faq_item_answer'),
(6818, 539, 'faq_items_12_category_slug', 'technical'),
(6819, 539, '_faq_items_12_category_slug', 'field_faq_item_topic_slug'),
(6820, 539, 'faq_items_12_question', 'How loud is Sleep Mode?'),
(6821, 539, '_faq_items_12_question', 'field_faq_item_question'),
(6822, 539, 'faq_items_12_answer', 'In Sleep Mode, the fan operates at a whisper-quiet 24 decibels — roughly the volume of rustling leaves, making it perfect for uninterrupted sleep.'),
(6823, 539, '_faq_items_12_answer', 'field_faq_item_answer'),
(6824, 539, 'faq_items_13_category_slug', 'shipping-warranty'),
(6825, 539, '_faq_items_13_category_slug', 'field_faq_item_topic_slug'),
(6826, 539, 'faq_items_13_question', 'How long does delivery take?'),
(6827, 539, '_faq_items_13_question', 'field_faq_item_question'),
(6828, 539, 'faq_items_13_answer', 'Standard delivery takes 3-5 business days to most metro locations across India.'),
(6829, 539, '_faq_items_13_answer', 'field_faq_item_answer'),
(6830, 539, 'faq_items_14_category_slug', 'shipping-warranty'),
(6831, 539, '_faq_items_14_category_slug', 'field_faq_item_topic_slug'),
(6832, 539, 'faq_items_14_question', 'What does the warranty cover?'),
(6833, 539, '_faq_items_14_question', 'field_faq_item_question'),
(6834, 539, 'faq_items_14_answer', 'We offer a comprehensive 2-year warranty that covers the motor and internal electronics. Physical damage and consumable filters are not covered.'),
(6835, 539, '_faq_items_14_answer', 'field_faq_item_answer'),
(6836, 539, 'faq_items_15_category_slug', 'shipping-warranty'),
(6837, 539, '_faq_items_15_category_slug', 'field_faq_item_topic_slug'),
(6838, 539, 'faq_items_15_question', 'Can I return the purifier if I\'m not satisfied?'),
(6839, 539, '_faq_items_15_question', 'field_faq_item_question'),
(6840, 539, 'faq_items_15_answer', 'Yes, we offer a 14-day risk-free trial. If you are not completely satisfied, you can return the unit within 14 days in its original condition and packaging.'),
(6841, 539, '_faq_items_15_answer', 'field_faq_item_answer'),
