(6904, 540, 'faq_items_0_category_slug', 'the-app'),
(6905, 540, '_faq_items_0_category_slug', 'field_faq_item_topic_slug'),
(6906, 540, 'faq_items_0_question', 'Which devices is the Breathe In app available on?'),
(6907, 540, '_faq_items_0_question', 'field_faq_item_question'),
(6908, 540, 'faq_items_0_answer', 'The app is available for download on both iOS (App Store) and Android (Google Play Store) devices running the latest software versions.'),
(6909, 540, '_faq_items_0_answer', 'field_faq_item_answer'),
(6910, 540, 'faq_items_1_category_slug', 'the-app'),
(6911, 540, '_faq_items_1_category_slug', 'field_faq_item_topic_slug'),
(6912, 540, 'faq_items_1_question', 'How many purifiers can I connect to one account?'),
(6913, 540, '_faq_items_1_question', 'field_faq_item_question'),
(6914, 540, 'faq_items_1_answer', 'You can connect and manage up to 50 purifiers on a single account, making it ideal for both residential  and large commercial setups.'),
(6915, 540, '_faq_items_1_answer', 'field_faq_item_answer'),
(6916, 540, 'faq_items_2_category_slug', 'the-app'),
(6917, 540, '_faq_items_2_category_slug', 'field_faq_item_topic_slug'),
(6918, 540, 'faq_items_2_question', 'Can I share access with family members?'),
(6919, 540, '_faq_items_2_question', 'field_faq_item_question'),
(6920, 540, 'faq_items_2_answer', 'Yes, using the \"Home Management\" feature in the app, you can invite family members to control the purifiers without them needing to re-pair the devices.'),
(6921, 540, '_faq_items_2_answer', 'field_faq_item_answer'),
