(6923, 540, '_faq_items', 'field_faq_items_repeater'),
(6924, 540, 'faq_topics_2_topic_name', 'Filters & Care'),
(6925, 540, '_faq_topics_2_topic_name', 'field_topic_name'),
(6926, 540, 'faq_topics_2_topic_slug', 'filters-care'),
(6927, 540, '_faq_topics_2_topic_slug', 'field_topic_slug'),
(6928, 540, 'faq_topics_3_topic_name', 'Technical'),
(6929, 540, '_faq_topics_3_topic_name', 'field_topic_name'),
(6930, 540, 'faq_topics_3_topic_slug', 'technical'),
(6931, 540, '_faq_topics_3_topic_slug', 'field_topic_slug'),
(6932, 540, 'faq_topics_4_topic_name', 'Shipping & Warranty'),
(6933, 540, '_faq_topics_4_topic_name', 'field_topic_name'),
(6934, 540, 'faq_topics_4_topic_slug', 'shipping-warranty'),
(6935, 540, '_faq_topics_4_topic_slug', 'field_topic_slug'),
(6936, 540, 'faq_items_3_category_slug', 'the-app'),
(6937, 540, '_faq_items_3_category_slug', 'field_faq_item_topic_slug'),
(6938, 540, 'faq_items_3_question', 'Does the app work without an internet connection?'),
(6939, 540, '_faq_items_3_question', 'field_faq_item_question'),
(6940, 540, 'faq_items_3_answer', 'To use remote control features from your phone, an active Wi-Fi connection is required. However, the physical touch panel on the purifier always works offline.'),
(6941, 540, '_faq_items_3_answer', 'field_faq_item_answer'),
(6942, 540, 'faq_items_4_category_slug', 'air-quality'),
(6943, 540, '_faq_items_4_category_slug', 'field_faq_item_topic_slug'),
(6944, 540, 'faq_items_4_question', 'What does the AQI number actually mean?'),
(6945, 540, '_faq_items_4_question', 'field_faq_item_question'),
(6946, 540, 'faq_items_4_answer', 'AQI stands for Air Quality Index. It is a standard scale used to communicate how polluted the air currently is. Lower numbers (0-50) indicate excellent air quality, while higher numbers indicate unsafe levels of particulate matter.'),
(6947, 540, '_faq_items_4_answer', 'field_faq_item_answer'),
(6948, 540, 'faq_items_5_category_slug', 'air-quality'),
(6949, 540, '_faq_items_5_category_slug', 'field_faq_item_topic_slug'),
(6950, 540, 'faq_items_5_question', 'What pollutants does the sensor measure?'),
(6951, 540, '_faq_items_5_question', 'field_faq_item_question'),
(6952, 540, 'faq_items_5_answer', 'Our laser sensors actively scan the air for PM2.5 (fine inhalable particles) and PM10 (dust and pollen). The Air Pro Max also includes a dedicated VOC sensor for harmful gases.'),
(6953, 540, '_faq_items_5_answer', 'field_faq_item_answer'),
(6954, 540, 'faq_items_6_category_slug', 'air-quality'),
(6955, 540, '_faq_items_6_category_slug', 'field_faq_item_topic_slug'),
(6956, 540, 'faq_items_6_question', 'Why is my indoor AQI sometimes higher than outdoor?'),
(6957, 540, '_faq_items_6_question', 'field_faq_item_question'),
(6958, 540, 'faq_items_6_answer', 'Indoor activities like cooking, using aerosols, burning incense, or sweeping can quickly elevate indoor pollution levels beyond outdoor levels due to poor ventilation.'),
(6959, 540, '_faq_items_6_answer', 'field_faq_item_answer'),
(6960, 540, 'faq_items_7_category_slug', 'filters-care'),
(6961, 540, '_faq_items_7_category_slug', 'field_faq_item_topic_slug'),
(6962, 540, 'faq_items_7_question', 'How often do I need to replace the filter?'),
(6963, 540, '_faq_items_7_question', 'field_faq_item_question'),
(6964, 540, 'faq_items_7_answer', 'Generally every 8 to 12 months, depending on usage and local air quality. The purifier and the app will notify you when it\'s time to replace it.'),
(6965, 540, '_faq_items_7_answer', 'field_faq_item_answer'),
(6966, 540, 'faq_items_8_category_slug', 'filters-care'),
(6967, 540, '_faq_items_8_category_slug', 'field_faq_item_topic_slug'),
(6968, 540, 'faq_items_8_question', 'Can I wash and reuse the HEPA filter?'),
(6969, 540, '_faq_items_8_question', 'field_faq_item_question'),
(6970, 540, 'faq_items_8_answer', 'No. Washing a HEPA filter destroys its delicate microscopic fibers. You can gently vacuum the outer pre-filter layer, but the main filter block must be replaced.'),
(6971, 540, '_faq_items_8_answer', 'field_faq_item_answer'),
(6972, 540, 'faq_items_9_category_slug', 'filters-care'),
(6973, 540, '_faq_items_9_category_slug', 'field_faq_item_topic_slug'),
(6974, 540, 'faq_items_9_question', 'Where can I buy replacement filters?'),
(6975, 540, '_faq_items_9_question', 'field_faq_item_question'),
(6976, 540, 'faq_items_9_answer', 'Genuine replacements are available directly on our website, through the Breathe In app, or via our official Amazon storefront.'),
(6977, 540, '_faq_items_9_answer', 'field_faq_item_answer'),
(6978, 540, 'faq_items_10_category_slug', 'technical'),
(6979, 540, '_faq_items_10_category_slug', 'field_faq_item_topic_slug'),
(6980, 540, 'faq_items_10_question', 'What Wi-Fi frequency does the purifier support?'),
(6981, 540, '_faq_items_10_question', 'field_faq_item_question'),
(6982, 540, 'faq_items_10_answer', 'Our purifiers currently support standard 2.4GHz Wi-Fi networks (which offer better range through walls). They will not connect to a 5GHz-only network.'),
(6983, 540, '_faq_items_10_answer', 'field_faq_item_answer'),
(6984, 540, 'faq_items_11_category_slug', 'technical'),
(6985, 540, '_faq_items_11_category_slug', 'field_faq_item_topic_slug'),
(6986, 540, 'faq_items_11_question', 'My purifier won\'t pair. What should I try?'),
(6987, 540, '_faq_items_11_question', 'field_faq_item_question'),
(6988, 540, 'faq_items_11_answer', 'Ensure your phone is connected to a 2.4GHz network. Press and hold the Wi-Fi button on the purifier panel for 5 seconds until it flashes rapidly, then retry the pairing process in the app.'),
(6989, 540, '_faq_items_11_answer', 'field_faq_item_answer'),
(6990, 540, 'faq_items_12_category_slug', 'technical'),
(6991, 540, '_faq_items_12_category_slug', 'field_faq_item_topic_slug'),
(6992, 540, 'faq_items_12_question', 'How loud is Sleep Mode?'),
(6993, 540, '_faq_items_12_question', 'field_faq_item_question'),
(6994, 540, 'faq_items_12_answer', 'In Sleep Mode, the fan operates at a whisper-quiet 24 decibels — roughly the volume of rustling leaves, making it perfect for uninterrupted sleep.'),
(6995, 540, '_faq_items_12_answer', 'field_faq_item_answer'),
(6996, 540, 'faq_items_13_category_slug', 'shipping-warranty'),
(6997, 540, '_faq_items_13_category_slug', 'field_faq_item_topic_slug'),
(6998, 540, 'faq_items_13_question', 'How long does delivery take?'),
(6999, 540, '_faq_items_13_question', 'field_faq_item_question'),
(7000, 540, 'faq_items_13_answer', 'Standard delivery takes 3-5 business days to most metro locations across India.'),
(7001, 540, '_faq_items_13_answer', 'field_faq_item_answer'),
(7002, 540, 'faq_items_14_category_slug', 'shipping-warranty'),
(7003, 540, '_faq_items_14_category_slug', 'field_faq_item_topic_slug'),
(7004, 540, 'faq_items_14_question', 'What does the warranty cover?'),
(7005, 540, '_faq_items_14_question', 'field_faq_item_question'),
(7006, 540, 'faq_items_14_answer', 'We offer a comprehensive 2-year warranty that covers the motor and internal electronics. Physical damage and consumable filters are not covered.'),
(7007, 540, '_faq_items_14_answer', 'field_faq_item_answer'),
(7008, 540, 'faq_items_15_category_slug', 'shipping-warranty'),
(7009, 540, '_faq_items_15_category_slug', 'field_faq_item_topic_slug'),
(7010, 540, 'faq_items_15_question', 'Can I return the purifier if I\'m not satisfied?'),
(7011, 540, '_faq_items_15_question', 'field_faq_item_question'),
(7012, 540, 'faq_items_15_answer', 'Yes, we offer a 14-day risk-free trial. If you are not completely satisfied, you can return the unit within 14 days in its original condition and packaging.'),
(7013, 540, '_faq_items_15_answer', 'field_faq_item_answer'),
