(517, 1, '2026-08-13 14:09:37', '2026-08-13 14:09:37', '<div class=\"flex flex-col gap-5 lg:gap-6\">\r\n\r\n  <!-- Company Name -->\r\n  <div class=\"flex flex-col\">\r\n    <label class=\"text-[10px] uppercase tracking-[0.15em] text-gray-500 font-bold mb-2\">Company / Organisation</label>\r\n    [text* company-name class:border class:border-gray-200 class:dark:border-gray-700 class:bg-gray-50 class:dark:bg-slate-900 class:text-sm class:text-gray-900 class:dark:text-white class:rounded-sm class:px-4 class:py-3.5 class:outline-none class:focus:border-cyan-600 class:transition-colors class:w-full placeholder \"Company name\"]\r\n  </div>\r\n\r\n  <!-- Contact Person & Phone Row -->\r\n  <div class=\"grid grid-cols-1 md:grid-cols-2 gap-5 lg:gap-6\">\r\n    <div class=\"flex flex-col w-full\">\r\n      <label class=\"text-[10px] uppercase tracking-[0.15em] text-gray-500 font-bold mb-2\">Contact Person</label>\r\n      [text* contact-person class:border class:border-gray-200 class:dark:border-gray-700 class:bg-gray-50 class:dark:bg-slate-900 class:text-sm class:text-gray-900 class:dark:text-white class:rounded-sm class:px-4 class:py-3.5 class:outline-none class:focus:border-cyan-600 class:transition-colors class:w-full placeholder \"Name\"]\r\n    </div>\r\n    <div class=\"flex flex-col w-full\">\r\n      <label class=\"text-[10px] uppercase tracking-[0.15em] text-gray-500 font-bold mb-2\">Phone</label>\r\n      [tel* phone-number class:border class:border-gray-200 class:dark:border-gray-700 class:bg-gray-50 class:dark:bg-slate-900 class:text-sm class:text-gray-900 class:dark:text-white class:rounded-sm class:px-4 class:py-3.5 class:outline-none class:focus:border-cyan-600 class:transition-colors class:w-full placeholder \"+91\"]\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Work Email -->\r\n  <div class=\"flex flex-col\">\r\n    <label class=\"text-[10px] uppercase tracking-[0.15em] text-gray-500 font-bold mb-2\">Work Email</label>\r\n    [email* work-email class:border class:border-gray-200 class:dark:border-gray-700 class:bg-gray-50 class:dark:bg-slate-900 class:text-sm class:text-gray-900 class:dark:text-white class:rounded-sm class:px-4 class:py-3.5 class:outline-none class:focus:border-cyan-600 class:transition-colors class:w-full placeholder \"you@company.com\"]\r\n  </div>\r\n\r\n  <!-- Space Type & Units Needed Row -->\r\n  <div class=\"grid grid-cols-1 md:grid-cols-2 gap-5 lg:gap-6\">\r\n    <div class=\"flex flex-col w-full\">\r\n      <label class=\"text-[10px] uppercase tracking-[0.15em] text-gray-500 font-bold mb-2\">Space Type</label>\r\n      [text space-type class:border class:border-gray-200 class:dark:border-gray-700 class:bg-gray-50 class:dark:bg-slate-900 class:text-sm class:text-gray-900 class:dark:text-white class:rounded-sm class:px-4 class:py-3.5 class:outline-none class:focus:border-cyan-600 class:transition-colors class:w-full placeholder \"Office\"]\r\n    </div>\r\n    <div class=\"flex flex-col w-full\">\r\n      <label class=\"text-[10px] uppercase tracking-[0.15em] text-gray-500 font-bold mb-2\">Approx. Units Needed</label>\r\n      [text approx-units class:border class:border-gray-200 class:dark:border-gray-700 class:bg-gray-50 class:dark:bg-slate-900 class:text-sm class:text-gray-900 class:dark:text-white class:rounded-sm class:px-4 class:py-3.5 class:outline-none class:focus:border-cyan-600 class:transition-colors class:w-full placeholder \"2–5\"]\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Total Area -->\r\n  <div class=\"flex flex-col\">\r\n    <label class=\"text-[10px] uppercase tracking-[0.15em] text-gray-500 font-bold mb-2\">Total Area (Optional)</label>\r\n    [text total-area class:border class:border-gray-200 class:dark:border-gray-700 class:bg-gray-50 class:dark:bg-slate-900 class:text-sm class:text-gray-900 class:dark:text-white class:rounded-sm class:px-4 class:py-3.5 class:outline-none class:focus:border-cyan-600 class:transition-colors class:w-full placeholder \"e.g. 5,000 sq ft\"]\r\n  </di